        float *out_row = out + (size_t)i * (size_t)C;
        float maxval = kNegInf;
        for (int j = 0; j < C; ++j) {
          if (inp_row[j] > maxval) maxval = inp_row[j];
        }
        double sum = 0.0;
        for (int j = 0; j < C; ++j) {
          float e = sycl::exp(inp_row[j] - maxval);
          out_row[j] = e;
